import{_ as n,o as t,c as r,a3 as i}from"./chunks/framework.BlfGB29P.js";const p=JSON.parse('{"title":"Projektduplicator 2026","description":"EEP-Modellprojekte duplizieren und bearbeiten, mit mehrsprachiger Oberfläche, ZIP-Snapshots und manuellen GitHub-Updates.","frontmatter":{"title":"Projektduplicator 2026","description":"EEP-Modellprojekte duplizieren und bearbeiten, mit mehrsprachiger Oberfläche, ZIP-Snapshots und manuellen GitHub-Updates."},"headers":[],"relativePath":"eep/projektduplicator-2026/index.md","filePath":"eep/projektduplicator-2026/index.md","lastUpdated":1793198184000}'),a={name:"eep/projektduplicator-2026/index.md"};function l(o,e,d,u,s,h){return t(),r("div",null,[...e[0]||(e[0]=[i('<h1 id="projektduplicator-2026" tabindex="-1">Projektduplicator 2026 <a class="header-anchor" href="#projektduplicator-2026" aria-label="Permalink to &quot;Projektduplicator 2026&quot;">​</a></h1><p>Projektduplicator 2026 ist das eigenständige Windows-Werkzeug von UGSo Software zum Duplizieren und Bearbeiten von EEP-Modellprojekten. Die Oberfläche unterstützt Deutsch, Englisch, Französisch und Niederländisch.</p><h2 id="download-und-start" tabindex="-1">Download und Start <a class="header-anchor" href="#download-und-start" aria-label="Permalink to &quot;Download und Start&quot;">​</a></h2><ul><li><a href="https://github.com/rockbaer2007/projektduplicator-2026/releases/download/v4.6.6.59/Projektduplicator-2026-v4.6.6.59-windows.zip" target="_blank" rel="noreferrer">Windows-ZIP 4.6.6.59 herunterladen</a></li><li><a href="https://github.com/rockbaer2007/projektduplicator-2026/releases/tag/v4.6.6.59" target="_blank" rel="noreferrer">Release, SHA-256-Prüfsumme und Quellcode</a></li><li><a href="https://github.com/rockbaer2007/projektduplicator-2026" target="_blank" rel="noreferrer">GitHub-Repository</a></li></ul><p>Das ZIP vollständig in einen beschreibbaren Ordner entpacken und <code>Projektduplicator_2017.exe</code> starten. Der technische Dateiname bleibt für die Kompatibilität vorhandener Einstellungen erhalten. Benötigt wird Windows mit .NET Framework 4.8; die Projektmappe lässt sich in Visual Studio 2026 bauen.</p><h2 id="funktionen" tabindex="-1">Funktionen <a class="header-anchor" href="#funktionen" aria-label="Permalink to &quot;Funktionen&quot;">​</a></h2><ul><li>EEP-Modellprojekte duplizieren und Modellinformationen bearbeiten.</li><li>Modellnamen und Beschreibungen mehrsprachig bearbeiten und über Google Translate übersetzen.</li><li>Sprache der Oberfläche während der Nutzung wechseln.</li><li>ZIP-Snapshots der Projekte im eingestellten Sicherungsordner erstellen.</li><li>Über die vorhandenen Update-Schaltflächen manuell neue GitHub-Releases prüfen, herunterladen und nach Bestätigung installieren.</li></ul><p>Die Google-Webübersetzung benötigt Internet und hängt vom Antwortformat der Google-Webseite ab. Sie verwendet keine offizielle Google-API. Bei einem Übersetzungsfehler bleiben die bisherigen Texte erhalten.</p><h2 id="einstellungen-und-updates" tabindex="-1">Einstellungen und Updates <a class="header-anchor" href="#einstellungen-und-updates" aria-label="Permalink to &quot;Einstellungen und Updates&quot;">​</a></h2><p>Vor Änderungen eigene Projekte sichern. Vor einem Update Editoren schließen und Änderungen an Pfad- und Spline-Listen speichern. Es gibt keine automatische Updateprüfung beim Start.</p><p>Der Updater prüft das Paket und seine SHA-256-Prüfsumme, sichert vorhandene Programmdateien und Einstellungen und startet nach erfolgreicher Installation neu. Vorhandene Projektdateien, Pfadlisten und eigene <code>info.txt</code>-Inhalte bleiben erhalten. Fehlt <code>info.txt</code>, wird die mitgelieferte Fassung installiert. Eine bestehende ältere <code>info.txt</code> wird absichtlich nicht automatisch ersetzt.</p><h2 id="geprufter-stand" tabindex="-1">Geprüfter Stand <a class="header-anchor" href="#geprufter-stand" aria-label="Permalink to &quot;Geprüfter Stand&quot;">​</a></h2><p>Version 4.6.6.59 wurde vom Nutzer lokal freigegeben. Der Form1-Designer wurde in Visual Studio geprüft. Die Beschreibung und Danksagungen in <code>info.txt</code> sind in DE/EN/FR/NL überarbeitet. 49 lokale Prüfungen decken unter anderem Sprachfassungen, Feldzuordnung, Paketprüfung, Datenerhalt, Abbruch, Rollback und den Prozesswechsel des Updaters ab.</p><p>Ein echter Updateablauf vom öffentlichen GitHub-Release mit Installation und Neustart ist noch gesondert zu prüfen. Die bisherigen Tests verwenden simulierte GitHub-Antworten und temporäre Installationen.</p><h2 id="quellcode-und-hinweise" tabindex="-1">Quellcode und Hinweise <a class="header-anchor" href="#quellcode-und-hinweise" aria-label="Permalink to &quot;Quellcode und Hinweise&quot;">​</a></h2><p>UGSo-Quellcode unter MIT; Abhängigkeiten behalten ihre jeweiligen Lizenzbedingungen und Copyright-Hinweise. Details stehen im Repository unter <code>LICENSE</code> und <code>THIRD-PARTY-NOTICES.md</code>. EEP und Google Translate sind Produkte ihrer jeweiligen Rechteinhaber.</p>',16)])])}const b=n(a,[["render",l]]);export{p as __pageData,b as default};
